<?php
require_once __DIR__.'/m0/bootstrap.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/Repository.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/Answers.php';
require_once EIPSI_FORMS_PLUGIN_DIR.'includes/assessment-editor/EngineMapper.php';
use EIPSI\AssessmentEditor\Definition as D;
use EIPSI\AssessmentEditor\Repository as R;
use EIPSI\AssessmentEditor\Answers as A;
use EIPSI\AssessmentEditor\EngineMapper as M;
$tests=0;$failures=0;$owned=array();
function ac_case($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo "FAIL $name: ".$e->getMessage()."\n";}}
function ac_assert($v,$message='Assertion failed'){if(!$v)throw new RuntimeException($message);}
function ac_reject($fn){try{$fn();}catch(Throwable $e){return;}throw new RuntimeException('Expected rejection');}
function ac_fixture(){return D::validate(json_decode(file_get_contents(__DIR__.'/assessment-editor/parity-fixture.json'),true));}
function ac_one($type){$d=ac_fixture();$d['elements']=array_values(array_filter($d['elements'],static function($e)use($type){return $e['type']===$type;}));return $d;}
function ac_errors($type,$value,$touched=true){$d=ac_one($type);return A::errors($d,array($d['elements'][0]['response_key']=>$value),array($d['elements'][0]['response_key']=>$touched));}
wp_set_current_user(1);
try {
foreach(array_diff(D::QUESTIONS,array('matrix')) as $type)ac_case($type.' maximal create/save/reload canonical parity',function()use($type,&$owned){$d=ac_one($type);$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];$normalized=D::validate($d);ac_assert(D::json($normalized)===D::json($d),'Fixture must already be normalized');R::save($d,0);ac_assert(D::json(R::load($d['id'])['definition'])===D::json($d));});
ac_case('v0 defaults are nondestructive and preserve options identities multiline labels',function()use(&$owned){$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/fixture.json'),true);$before=D::json($d);$normalized=D::validate($d);ac_assert(D::json($d)===$before);foreach($d['elements'] as $i=>$e){ac_assert($e['id']===$normalized['elements'][$i]['id']);$options=$normalized['elements'][$i]['options'];if(in_array($e['type'],array('likert','matrix'),true))foreach($options as $j=>&$option){ac_assert($option['value']===($e['properties']['min']??1)+$j);unset($option['value']);}unset($option);ac_assert($e['options']===$options);}$vas=array_values(array_filter($normalized['elements'],static function($e){return $e['type']==='vas';}))[0];ac_assert($vas['properties']['labels']===array($vas['properties']['left_label'],$vas['properties']['right_label']));$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];R::save($d,0);ac_assert(D::json(R::load($d['id'])['definition'])===D::json(D::validate($d)));});
ac_case('required enforced by pure backend for every question type',function(){foreach(array_diff(D::QUESTIONS,array('matrix')) as $type)ac_assert(count(A::errors(ac_one($type),array()))===1,$type);});
ac_case('text family length email URL date formats and valid values',function(){foreach(array(array('text','x'),array('textarea',str_repeat('x',101)),array('email','bad@email'),array('url','relative/path'),array('date','2026-02-30'),array('date','0000-01-01')) as $bad)ac_assert(count(ac_errors($bad[0],$bad[1]))===1,$bad[0]);foreach(array(array('text','ok'),array('textarea',"Largo\ntexto"),array('email','a@example.test'),array('url','https://example.test/path'),array('date','2024-02-29'),array('tel','+54 11')) as $good)ac_assert(!ac_errors($good[0],$good[1]),$good[0]);});
ac_case('number decimal bounds and zero remain numeric without coercion',function(){foreach(array(-2.25,0,7.5,0.1) as $v)ac_assert(!ac_errors('number',$v));foreach(array(-2.75,7.75,'0',true) as $v)ac_assert(count(ac_errors('number',$v))===1);});
ac_case('multiple cardinality membership duplicate identity and array shape',function(){$d=ac_one('multiple_choice');$ids=array_column($d['elements'][0]['options'],'id');ac_assert(!ac_errors('multiple_choice',array_slice($ids,0,2)));foreach(array(array($ids[0]),array_slice($ids,0,4),array($ids[0],$ids[0]),array($ids[0],'wrong'),array('key'=>$ids[0])) as $bad)ac_assert(count(ac_errors('multiple_choice',$bad))===1);});
ac_case('select placeholder remains unanswered and stable IDs required',function(){ac_assert(count(ac_errors('select',''))===1);ac_assert(count(ac_errors('select','Sí, a veces'))===1);ac_assert(!ac_errors('select','O_select_0'));});
ac_case('Likert reverse preserves numeric projection and canonical options',function(){$d=ac_one('likert');$e=$d['elements'][0];$v=A::value($e,$e['options'][0]['id']);ac_assert($v===-3);$e['properties']['reversed']=false;ac_assert(A::value($e,$e['options'][0]['id'])===$v);ac_assert(!ac_errors('likert',$e['options'][0]['id']));});
ac_case('VAS untouched same initial decimal step and hidden display semantics',function(){ac_assert(count(ac_errors('vas',2.5,false))===1);ac_assert(!ac_errors('vas',2.5,true));ac_assert(!ac_errors('vas',-2.25,true));ac_assert(count(ac_errors('vas',2.6,true))===1);$d=ac_one('vas');$d['elements'][0]['properties']['show_value']=false;ac_assert(!A::errors($d,array('R_vas'=>2.5),array('R_vas'=>true)));});
ac_case('schema rejects invalid cardinality rows lengths gradients and VAS presentation',function(){foreach(array(array('multiple_choice','min_selected',6),array('multiple_choice','max_selected',1),array('textarea','rows',0),array('text','min_length',101),array('number','step',0),array('likert','min',1.5),array('likert','reversed','yes'),array('vas','label_alignment',101),array('vas','label_font_size',37),array('vas','value_font_size',73),array('vas','value_position','left'),array('vas','labels',array()),array('vas','gradient_start','url(javascript:1)'),array('vas','gradient','unknown')) as $bad){$d=ac_one($bad[0]);$d['elements'][0]['properties'][$bad[1]]=$bad[2];ac_reject(function()use($d){D::validate($d);});}});
ac_case('option rename reorder duplicate labels remain analytically distinguishable',function(){$d=ac_one('single_choice');$e=&$d['elements'][0];$first=$e['options'][0]['id'];$e['options'][0]['label']='Renamed';$e['options']=array_reverse($e['options']);D::validate($d);ac_assert(in_array($first,array_column($e['options'],'id'),true));ac_assert(count(array_unique(array_column($e['options'],'id')))===count($e['options']));$e['options'][0]['id']=$e['options'][1]['id'];ac_reject(function()use($d){D::validate($d);});});
ac_case('Engine preserves maximal presentation metadata with explicit warnings',function(){foreach(array('text','email','number','tel','textarea','single_choice','select','likert','vas') as $type){$d=ac_one($type);$mapped=M::map($d)->toArray();ac_assert(D::json($mapped['protocol_metadata']['native_definition'])===D::json($d),$type);ac_assert(!empty($mapped['protocol_metadata']['mapping_warnings']));$q=array_values(array_filter($mapped['nodes'],static function($n){return $n['kind']==='QUESTION';}))[0];ac_assert($q['id']===$d['elements'][0]['id']);if($type==='likert')ac_assert($q['validation']['min']===-3);}});
ac_case('Engine rejects Date URL Multiple entire export without writes',function(){$before=count(R::listing());foreach(array('date','url','multiple_choice') as $type)ac_reject(function()use($type){M::map(ac_one($type));});ac_assert(count(R::listing())===$before);});
ac_case('unknown answer keys rejected without coercion or persistence',function(){$d=ac_one('text');$errors=A::errors($d,array('R_text'=>'ok','unexpected'=>'bad'));ac_assert(count($errors)===1&&$errors[0]['id']==='unexpected');});
ac_case('VAS unanswered value message saves reloads and rejects nontext values',function()use(&$owned){$d=ac_one('vas');$d['id']='AE_'.bin2hex(random_bytes(12));$owned[]=$d['id'];$d['elements'][0]['properties']['unanswered_value_message']='Elegí un valor';R::save($d,0);ac_assert(R::load($d['id'])['definition']['elements'][0]['properties']['unanswered_value_message']==='Elegí un valor');$d['elements'][0]['properties']['unanswered_value_message']=array('bad');ac_reject(function()use($d){D::validate($d);});});
ac_case('VAS permits nonaligned maximum while initial and answers stay on step grid',function(){$d=ac_one('vas');$d['elements'][0]['properties']['max']=7.6;D::validate($d);ac_assert(!A::errors($d,array('R_vas'=>7.5),array('R_vas'=>true)));ac_assert(count(A::errors($d,array('R_vas'=>7.6),array('R_vas'=>true)))===1);});
ac_case('normalization is idempotent across maximal and v0 documents',function(){foreach(array(ac_fixture(),json_decode(file_get_contents(__DIR__.'/assessment-editor/fixture.json'),true)) as $d){$first=D::validate($d);ac_assert(D::json(D::validate($first))===D::json($first));}});
}finally{wp_set_current_user(1);foreach($owned as $id)delete_option(R::PREFIX.$id);}
echo "$tests tests, $failures failures\n";exit($failures?1:0);
